data.logic_rule:
let src = input.cases || []
let reps = input.reps || 1
let queue = []
let r = 1
while (r <= reps) {
  src.forEach(function (c) {
    queue.push({ id: c.id + '#' + r, base: c.id, expect: c.expect, acceptable: c.acceptable, text: c.text })
  })
  r = r + 1
}
let fresh = { i: 0, results: [], report: null, queue: queue }
fresh

let d = input.decision || {}
let a = d.answers || {}
let pick = function (q) {
  let r = a[q] || {}
  return { answer: r.answer, confidence: r.confidence }
}
let c = input.current || {}
let row = {
  id: c.id,
  base: c.base,
  expect: c.expect,
  acceptable: c.acceptable,
  fired_port: input.fired_port,
  category: pick('category'),
  urgency: pick('urgency'),
  needs_human: pick('needs_human')
}
let prior = input.results || []
let seen = prior.filter(function (r) { return r.id === row.id })
let results = seen.length ? prior : prior.concat([row])
results

let rows = input.results || []
let cat = function (r) { return (r.category || {}).answer }
let urg = function (r) { return (r.urgency || {}).answer }
let hum = function (r) { return (r.needs_human || {}).answer }
let ok = function (r) {
  let got = cat(r)
  if (r.acceptable && r.acceptable.length) { return r.acceptable.indexOf(got) >= 0 }
  return got === r.expect
}
let bases = []
rows.forEach(function (r) { if (bases.indexOf(r.base) < 0) { bases.push(r.base) } })
let uniq = function (xs) {
  let out = []
  xs.forEach(function (x) { if (out.indexOf(x) < 0) { out.push(x) } })
  return out
}
let stability = bases.map(function (b) {
  let reps = rows.filter(function (r) { return r.base === b })
  let cats = uniq(reps.map(cat))
  let urgs = uniq(reps.map(urg))
  let confs = reps.map(function (r) { return (r.category || {}).confidence || 0 }).sort(function (x, y) { return x - y })
  return {
    base: b,
    expect: reps[0].expect,
    reps: reps.length,
    category: cats,
    category_stable: cats.length === 1,
    conf_min: confs[0],
    conf_max: confs[confs.length - 1],
    urgency: urgs,
    urgency_stable: urgs.length === 1,
    needs_human: uniq(reps.map(hum)),
    all_reps_correct: reps.filter(ok).length === reps.length
  }
})
let scorable = rows.filter(function (r) { return r.expect !== 'ambiguous' })
let humAll = uniq(rows.map(hum))
let report = {
  rows: rows.length,
  distinct_cases: bases.length,
  category_accuracy_all_reps: scorable.length ? scorable.filter(ok).length / scorable.length : 0,
  unstable_category: stability.filter(function (s) { return !s.category_stable }).map(function (s) { return s.base }),
  unstable_urgency: stability.filter(function (s) { return !s.urgency_stable }).map(function (s) { return s.base }),
  needs_human_distinct_answers: humAll,
  exceptions: rows.filter(function (r) { return r.fired_port === '_exception' }).length,
  routing_mismatches: rows.filter(function (r) { return r.fired_port !== 'category.' + cat(r) }).length,
  stability: stability
}
report
